def combination_sum(candidates: list[int], target: int) -> list[list[int]]:
    """Distinct positive candidates, each reusable: every multiset that sums to target."""
    nums = sorted(candidates)
    res, path = [], []

    def dfs(start: int, remain: int) -> None:
        if remain == 0:
            res.append(path[:])
            return
        for i in range(start, len(nums)):
            if nums[i] > remain:
                break  # sorted: every later candidate is too big as well
            path.append(nums[i])
            dfs(i, remain - nums[i])  # i, not i + 1: the same number may come again
            path.pop()

    dfs(0, target)
    return res

