// Best total value within capacity cap, each item at most once.
int knapsack01(const vector<int>& weights, const vector<int>& values, int cap) {
    vector<int> dp(cap + 1, 0);  // dp[c]: best value with capacity c
    for (size_t i = 0; i < weights.size(); i++)
        for (int c = cap; c >= weights[i]; c--)  // backwards: item i is used at most once
            dp[c] = max(dp[c], dp[c - weights[i]] + values[i]);
    return dp[cap];
}

