// knapsack01 returns the best total value within capacity cap, each item at most once.
func knapsack01(weights, values []int, capacity int) int {
	dp := make([]int, capacity+1) // dp[c]: best value with capacity c
	for i, w := range weights {
		for c := capacity; c >= w; c-- { // backwards: item i is used at most once
			dp[c] = max(dp[c], dp[c-w]+values[i])
		}
	}
	return dp[capacity]
}

