	for _, x := range nums {
		total += x
	}
	if total%2 != 0 {
		return false
	}
	target := total / 2
	dp := make([]bool, target+1) // dp[s]: some subset sums to s
	dp[0] = true
	for _, x := range nums {
		for s := target; s >= x; s-- { // backwards: x is used at most once
			dp[s] = dp[s] || dp[s-x]
		}
	}
	return dp[target]
