// Fewest coins (each reusable) that sum to amount, or -1.
int minCoins(const vector<int>& coins, int amount) {
    const int INF = amount + 1;  // more coins than any answer can need
    vector<int> dp(amount + 1, INF);  // dp[s]: fewest coins for sum s
    dp[0] = 0;
    for (int coin : coins)
        for (int s = coin; s <= amount; s++)  // forwards: the coin may be reused
            dp[s] = min(dp[s], dp[s - coin] + 1);
    return dp[amount] < INF ? dp[amount] : -1;
}

