def count_sequences(nums: list[int], target: int) -> int:
    """Ordered ways to reach target with unlimited reuse: (1, 2) and (2, 1) differ."""
    dp = [1] + [0] * target  # dp[s]: sequences that sum to s
    for s in range(1, target + 1):  # sums outside: each sum tries every last pick
        for x in nums:
            if x <= s:
                dp[s] += dp[s - x]
    return dp[target]

