def max_strings(strs: list[str], m: int, n: int) -> int:
    """Most strings you can pick with at most m zeros and n ones in total."""
    dp = [[0] * (n + 1) for _ in range(m + 1)]  # dp[i][j]: best with i zeros, j ones
    for s in strs:
        zeros, ones = s.count("0"), s.count("1")
        for i in range(m, zeros - 1, -1):  # both capacities backwards: s is used once
            for j in range(n, ones - 1, -1):
                dp[i][j] = max(dp[i][j], dp[i - zeros][j - ones] + 1)
    return dp[m][n]

