int maxStrings(const vector<string>& strs, int m, int n) {
    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));  // dp[i][j]: best with i zeros, j ones
    for (const string& s : strs) {
        int zeros = count(s.begin(), s.end(), '0'), ones = (int)s.size() - zeros;
        for (int i = m; i >= zeros; i--)  // both capacities backwards: s is used once
            for (int j = n; j >= ones; j--)
                dp[i][j] = max(dp[i][j], dp[i - zeros][j - ones] + 1);
    }
    return dp[m][n];
}

