import "strings"

// maxStrings returns the most strings you can pick with at most m zeros and n ones.
func maxStrings(strs []string, m, n int) int {
	dp := make([][]int, m+1) // dp[i][j]: best with i zeros, j ones
	for i := range dp {
		dp[i] = make([]int, n+1)
	}
	for _, s := range strs {
		zeros := strings.Count(s, "0")
		ones := len(s) - zeros
		for i := m; i >= zeros; i-- { // both capacities backwards: s is used once
			for j := n; j >= ones; j-- {
				dp[i][j] = max(dp[i][j], dp[i-zeros][j-ones]+1)
			}
		}
	}
	return dp[m][n]
}

