// Best value within cap when item i has counts[i] copies.
int boundedKnapsack(const vector<int>& weights, const vector<int>& values, const vector<int>& counts, int cap) {
    vector<int> dp(cap + 1, 0);
    for (size_t i = 0; i < weights.size(); i++) {
        int w = weights[i], v = values[i], cnt = counts[i];
        for (int k = 1; cnt > 0; k *= 2) {  // bundles of 1, 2, 4, ... copies, then the rest
            int take = min(k, cnt);
            cnt -= take;
            for (int c = cap; c >= take * w; c--)  // each bundle is one 0/1 item
                dp[c] = max(dp[c], dp[c - take * w] + take * v);
        }
    }
    return dp[cap];
}

