// boundedKnapsack returns the best value within capacity when item i has counts[i] copies.
func boundedKnapsack(weights, values, counts []int, capacity int) int {
	dp := make([]int, capacity+1)
	for i, w := range weights {
		v, cnt := values[i], counts[i]
		for k := 1; cnt > 0; k *= 2 { // bundles of 1, 2, 4, ... copies, then the rest
			take := min(k, cnt)
			cnt -= take
			for c := capacity; c >= take*w; c-- { // each bundle is one 0/1 item
				dp[c] = max(dp[c], dp[c-take*w]+take*v)
			}
		}
	}
	return dp[capacity]
}

